/**
 * Shared receipt printing utility used by both POS and Sales Reports.
 */

// Helper functions
const escapeHtml = (text) => {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
};

const capitalize = (str) => {
  if (!str) return '';
  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
};

const currency = (amount) => {
  return `₦${Number(amount).toLocaleString()}`;
};

const round = (num) => {
  // Align with POS and SalesTable: round to nearest 100
  return Math.round((Number(num) || 0) / 100) * 100;
};

const getVendorName = (vendorId, vendors) => {
  if (!vendors || !Array.isArray(vendors)) {
    // console.log('getVendorName: vendors array missing or invalid', vendors);
    return vendorId || 'Unknown';
  }
  
  // Log structure of first vendor for debugging
  if (vendors.length > 0) {
    // console.log('Sample Vendor Object Map:', Object.keys(vendors[0]));
  }

  // Handle case where vendorId might be an object
  const searchId = (typeof vendorId === 'object' && vendorId !== null) 
    ? (vendorId.id || vendorId.vendor_id || vendorId._id || JSON.stringify(vendorId))
    : vendorId;

  const vendor = vendors.find(v => {
    const vid = v.id || v.vendor_id || v._id;
    return String(vid) === String(searchId);
  });

  const result = vendor ? vendor.name : (searchId || 'Unknown');
  // console.log(`getVendorName: Input=${JSON.stringify(vendorId)}, SearchID=${searchId}, MatchedName=${result}`);
  return result;
};

export const openPrintWindow = (sale, vendors = [], options = {}) => {
  const { isBill = false, isKitchenCopy = false, targetVendorId = null } = options;
  if (!sale || !sale.items || sale.items.length === 0) return;

  const win = window.open('', 'PRINT', 'height=800,width=400');
  const saleDate = new Date(sale.date || Date.now());
  const formattedDate = saleDate.toLocaleString();
  const logoBase64 = 'data:image/png;base64,'; // You can embed a base64 logo here if needed
   // You can embed a base64 logo here if needed
  
  // Filter items if targetVendorId is provided (for kitchen/bar specific copies)
  const itemsToPrint = targetVendorId 
    ? sale.items.filter(item => String(item.vendor_id || item.selectedVendor) === String(targetVendorId))
    : sale.items;

  if (itemsToPrint.length === 0) {
    if (win) win.close();
    return;
  }

  let lineTotalSum = 0;
  const itemsHtml = itemsToPrint.map((item, index) => {
    const name = item.name || item.product_name || 'Item';      
    
    // 🔍 Vendor lookup logic
    const rawVendorId = item.vendor_id || item.vendorId || item.vendor;
    const existingName = item.vendor_name || (typeof item.vendor === 'string' ? item.vendor : null);
    
    let vendorName = 'Vendor';
    
    if (existingName && isNaN(existingName)) {
      vendorName = existingName;
    } else if (rawVendorId) {
      vendorName = getVendorName(rawVendorId, vendors);
    }

    const qty = item.quantity || item.qty || 1;
    // Align price calculation with POS logic: round selling_price to 100, then add commission
    const price = (Number(round(item.selling_price)) || 0) + (Number(item.custom_commission || item.commission) || 0);
    const lineTotal = (price * qty);
    lineTotalSum += lineTotal;
    
    return `
      <div class="line-item">
        <div class="item-left">
          <div class="item-name">${escapeHtml(name)}</div>
          <div class="item-vendor">${vendorName}</div>
        </div>
        <div class="item-right">
          <div class="item-qty">x${qty}</div>
          <div class="item-price">${currency(lineTotal)}</div>
        </div>
      </div>
    `;
  }).join('');

  // Use the calculated sum for totals
  const finalTotal = lineTotalSum;

  let paymentHtml = '';
  if (!isBill && !isKitchenCopy) {
    paymentHtml = (sale.payment && Array.isArray(sale.payment.breakdown) && sale.payment.breakdown.length > 0)
      ? sale.payment.breakdown.map(p => {
          const isMultiple = sale.payment.breakdown.length > 1;
          const amtRounded = isMultiple 
            ? round(Number(p.amount || 0))
            : finalTotal;
          
          return `<div class="pay-row">
                    <div class="pay-method">${escapeHtml(capitalize(p.method))}</div>
                    <div class="pay-amt">${currency(amtRounded)}</div>
                  </div>`;
        }).join('')
      : `<div class="pay-row">
            <div class="pay-method">${escapeHtml(capitalize(sale.payment?.type || 'Cash'))}</div>
            <div class="pay-amt">${currency(finalTotal)}</div>
          </div>`;
  } else if (isBill) {
    paymentHtml = `<div class="pay-row">
                    <div class="pay-method" style="color:black; font-weight:bold;">TOTAL DUE</div>
                    <div class="pay-amt" style="color:black; font-weight:bold;">${currency(finalTotal)}</div>
                  </div>`;
  }

  const titleText = isKitchenCopy ? "KITCHEN ORDER" : (isBill ? "BILL / ESTIMATE" : "OFFICIAL RECEIPT");
  const billInfo = (sale.bill_no || sale.billNo) ? `<div class="meta"><span style="font-weight:700">Bill/Table No:</span> ${escapeHtml(sale.bill_no || sale.billNo)}</div>` : ''; 

  const html = `
    <html>
      <head>
        <title>${titleText}</title>
        <meta charset="utf-8" />
        <style>
/* ============================================
   STANDARD 80mm THERMAL RECEIPT PRINTER SETTINGS
   ============================================
   - Width: 80mm (3.15 inches) - INDUSTRY STANDARD
   - Font: 12px minimum for readability
   - Line spacing: adequate for thermal printing
   - This matches most POS thermal printers
   ============================================ */

@page {
  size: 80mm auto; /* auto height = continuous paper */
  margin: 0;
}

html, body {
  width: 80mm;
  margin: 0;
  padding: 0;
  font-family: 'Arial', 'Helvetica', sans-serif; /* Changed from monospace for clarity */
  font-size: 12px; /* Increased from 10px - CRITICAL for readability */
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
  color: #000;
  background: #fff;
}

.receipt {
  width: 100%;
  box-sizing: border-box;
  padding: 8mm 5mm; /* Increased padding for better margins */
  min-height: 150mm; /* Minimum height to prevent too-short receipts */
}

.center { 
  text-align: center; 
}

.logo-placeholder {
  width: 75px;
  height: 75px;
  display: block;
  margin: 0 auto 10px;
  object-fit: contain;
}

.receipt-title {
  display: inline-block;
  background: #000;
  color: #fff;
  padding: 4px 12px;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 15px;
  border-radius: 2px;
}

h2.store {
  font-size: 14px; /* Increased for readability */
  margin: 6px 0;
  font-weight: 700;
}

.meta { 
  font-size: 11px; /* Increased from 9px */
  margin-bottom: 8px;
  text-align: center;
  color: #333;
}

.sep { 
  border-top: 1px dashed #444; 
  margin: 10px 0;
}

.sep-double {
  border-top: 3px double #000;
  margin: 12px 0;
}

.receipt-end-space {
  height: 25mm; /* More space at end for clean tear-off */
}

/* === ITEM LINES === */
.line-item {
  display: flex;
  justify-content: space-between;
  margin: 10px 0;
  padding-bottom: 8px;
  border-bottom: 1px dashed #eee;
}

.item-left {
  flex: 1;
  padding-right: 10px;
}

.item-name {
  font-weight: 700;
  font-size: 12px;
  color: #000;
  text-transform: uppercase;
}

.item-vendor {
  font-size: 11px;
  color: #d91f22;
  font-weight: 700;
  margin-top: 2px;
}

.item-right {
  text-align: right;
  min-width: 80px;
}

.item-qty {
  font-size: 11px;
  color: #666;
  font-weight: 600;
}

.item-price {
  font-size: 13px;
  font-weight: 800;
  margin-top: 2px;
}

.item-qty {
  font-size: 11px;
  color: #666;
}

.item-price {
  font-size: 12px;
  font-weight: 700;
  margin-top: 2px;
}

/* === TOTALS === */
.totals { 
  font-size: 12px; /* Increased */
  margin-top: 8px;
  padding: 0;
}

.totals .row { 
  display: flex; 
  justify-content: space-between; 
  margin: 6px 0; /* More spacing */
  font-weight: 700;
}

.totals .row div:last-child {
  font-size: 14px; /* Larger total amount */
  font-weight: 700;
}

/* === PAYMENT === */
.payment { 
  margin-top: 10px; 
  font-size: 12px; /* Increased */
}

.payment > div:first-child {
  font-weight: 700;
  margin-bottom: 6px;
  font-size: 12px;
}

.pay-row { 
  display: flex; 
  justify-content: space-between; 
  margin: 4px 0;
  font-size: 12px;
}

.pay-method {
  font-weight: 600;
}

.pay-amt {
  font-weight: 700;
}

/* === FOOTER === */
.thankyou { 
  margin-top: 15px; 
  text-align: center; 
  font-size: 12px; /* Increased */
  line-height: 1.6;
}

.small { 
  font-size: 10px; /* Increased from 9px */
  color: #666;
  margin-top: 4px;
}

/* === PRINT-SPECIFIC === */
@media print {
  body {
    background: white;
  }
}
</style>
      </head>
      <body>
        <div class="receipt">
          <div class="center">
            <div><img src="${options.tenantLogo || logoBase64}" alt="business-logo" class="logo-placeholder" /></div>
            <div class="receipt-title">${titleText}</div>
            <div class="meta" style="color:#000; font-weight:600;">${formattedDate}</div>
            ${billInfo}
            <div class="meta"><span style="font-weight:700">Customer:</span> ${escapeHtml(capitalize(sale.payment?.customer_type || 'Walk-in'))}</div>
          </div>

          <div class="sep-double"></div>

          ${itemsHtml}

          <div class="sep-double"></div>

          <div class="totals">
            <div class="row">
              <div style="font-size: 16px;">TOTAL DUE</div>
              <div style="font-size: 18px; border-bottom: 2px solid #000;">${currency(finalTotal)}</div>
            </div>
          </div>

          <div class="sep"></div>

          <div class="payment">
            <div>PAYMENT</div>
            ${paymentHtml}
          </div>

          <div class="sep"></div>

          <div class="thankyou">
            ${isKitchenCopy ? '' : '<div style="font-weight:600">Thank you for shopping!</div>'}
            <div style="font-weight:600; margin-top: 5px;">Thank you for choosing Deesoftwork</div>
            <div class="small">Powered by Deesoftwork</div>
          </div>
          
          <div class="receipt-end-space"></div>
        </div>
      </body>
    </html>
  `;

  win.document.open();
  win.document.write(html);
  win.document.close();

  win.focus();
  
  // Small delay to ensure rendering before print
  setTimeout(() => {
    win.print();
  }, 250);
};